'use strict';
// CIS 304 is deliberately isolated from the CIS 320 data and saved progress.
const KEY304='cis304-module1-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const shuffledOrder=a=>{const b=shuffle(a);if(b.length>1&&b.every((x,i)=>x===a[i]))b.push(b.shift());return b};
const paragraphs=s=>String(s||'').split(/\n+/).filter(Boolean).flatMap(p=>{const sentences=p.split(/(?<=[.!?])\s+(?=[A-Z])/),chunks=[];for(let i=0;i<sentences.length;i+=2)chunks.push(sentences.slice(i,i+2).join(' '));return chunks}).map(p=>`<p>${esc(p)}</p>`).join('');
let D,section=0,view='teach',session=null,lesson=null,storageOK=true;
let progress={cards:{},lessons:{},xp:0,days:[]};
try{const p=JSON.parse(localStorage.getItem(KEY304));if(p&&p.cards&&typeof p.cards==='object'&&!Array.isArray(p.cards)&&typeof p.xp==='number'&&Array.isArray(p.days))progress={...progress,...p,lessons:p.lessons||{}}}catch{storageOK=false}
function save(){try{localStorage.setItem(KEY304,JSON.stringify(progress))}catch{storageOK=false}stats()}
function stats(){$('#stats').innerHTML=`<span>✦ ${progress.xp} XP</span><span>${progress.days.length} study day${progress.days.length===1?'':'s'}</span>`;$('#storage-status').textContent=storageOK?'CIS 304 progress saves separately in this browser.':'Browser storage is unavailable. Progress will last only for this visit.'}
function record(x,ok){const old=progress.cards[x.id]||{seen:0,level:0};const level=ok?Math.min(6,old.level+1):0;progress.cards[x.id]={seen:old.seen+1,level,completed:old.completed||ok,due:Date.now()+(ok?[1,3,7,14,30,60][level-1]*86400000:60000)};progress.xp+=ok?10:2;const day=new Date().toLocaleDateString('en-CA');if(!progress.days.includes(day))progress.days.push(day);save()}
const filtered=items=>section?items.filter(x=>x.section===section):items;
const completed=x=>!!progress.cards[x.id]?.completed;
const sec=id=>D.sections.find(s=>s.id===id);
const source=x=>x.number?x:D.questions.find(q=>q.number===x.source);
const label=x=>`Module I · ${sec(x.section).title}`;
function sources(x){const q=source(x);if(!q)return '';return `<details class="question-source"><summary>Source & study-guide connection</summary><p>Original guide prompt ${q.number}: ${esc(q.q)}</p><p class="source-note">${q.slides.length?'Course slide'+(q.slides.length>1?'s ':' ')+q.slides.join(', ')+'.':'Refresher/guide topic; answer supplemented for study.'} Answers and examples are study explanations, not an instructor-issued answer key.</p>${D.references.filter(r=>r.questions.includes(q.number)).map(r=>`<p><a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.title)}</a></p>`).join('')}</details>`}
function picker(){return `<label class="tiny">Module I topic <select id="section"><option value="0">All topics</option>${D.sections.map(s=>`<option value="${s.id}" ${s.id===section?'selected':''}>${s.title}</option>`).join('')}</select></label>`}
function heading(t,p){return `<div class="heading"><div><div class="eyebrow">CIS 304 / ENTERPRISE ARCHITECTURE</div><h1>${esc(t)}</h1><p class="muted">${esc(p)}</p></div>${picker()}</div>`}
const navs=[['teach','☀','Learn First'],['practice','◈','Practice'],['flash','▤','Flashcards'],['map','▧','See the connections'],['exam','✓','Practice exam']];
const focused=[['apply','◎','Apply your knowledge'],['sort','≋','Sorting & sequences'],['abbrev','⌁','Abbreviations'],['math','#','Formula lab']];
const reference=[['terms','Aa','Terms & definitions'],['guide','☷','Full answered guide'],['readings','↗','Assigned readings']];
function buttonNav([id,icon,title]){return `<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon} &nbsp; ${title}</button>`}
function chrome(){stats();$('#nav').innerHTML=navs.map(buttonNav).join('')+`<details ${focused.some(x=>x[0]===view)?'open':''}><summary>Focused practice</summary>${focused.map(buttonNav).join('')}</details><details ${reference.some(x=>x[0]===view)?'open':''}><summary>Reference library</summary>${reference.map(buttonNav).join('')}</details>`;$('#modebar').innerHTML=`<button data-view="teach" class="${view==='teach'?'active':''}">Learn First</button><button data-view="practice" class="${view==='practice'?'active':''}">Practice Quiz</button><span class="tiny muted">CIS 304 · Module I</span>`}
function navigate(v){view=v;session=null;lesson=null;render();window.scrollTo(0,0)}
function render(){chrome();const fn={teach:teachHome,practice:practiceHome,flash:flashHome,map:mapHome,exam:examHome,apply:applyHome,sort:sortHome,abbrev:abbrevHome,math:mathHome,terms:termsHome,guide:guideHome,readings:readingsHome}[view];fn();const p=$('#section');if(p)p.onchange=()=>{section=+p.value;render()}}
function teachHome(){const sections=section?D.sections.filter(s=>s.id===section):D.sections;$('#app').innerHTML=heading('Understand it before you memorize it.','Start with a plain explanation, see a concrete example, then practice. Every original guide prompt has its own lesson.')+`<div class="notice">Your study guide sets the scope: all 51 prompts are included. The four sections below follow the refresher and Reading Sets 1–3. Added checks practice these same topics.</div>`+sections.map(s=>{const qs=D.questions.filter(q=>q.section===s.id),done=qs.filter(q=>progress.lessons[q.id]).length;return `<section class="card" style="margin-top:22px"><span class="tag">${esc(s.reading)}</span><h2>${s.id}. ${esc(s.title)}</h2><p>${esc(s.intro)}</p><div class="bar"><span style="width:${100*done/qs.length}%"></span></div><p class="tiny">${done} / ${qs.length} lessons completed</p><div class="lesson-list">${qs.map(q=>`<button data-lesson="${q.number}"><span class="badge">${q.number}</span><span class="lesson-label">${esc(q.title)}<small>${esc(q.q)}</small></span><span aria-label="${progress.lessons[q.id]?'Completed':'Not completed'}">${progress.lessons[q.id]?'✓':'→'}</span></button>`).join('')}</div></section>`}).join('')}
function openLesson(number,step=0){view='teach';session=null;lesson={number,step};chrome();const q=D.questions.find(q=>q.number===number);const steps=['Start with the idea','The complete answer','A concrete example'];$('#app').innerHTML=`<div class="study"><div class="row spread"><span class="tag">${label(q)} · Guide ${q.number} / 51</span><button data-view="teach">All lessons</button></div><h1>${esc(q.title)}</h1><div class="bar"><span style="width:${100*(step+1)/3}%"></span></div><section class="card lesson-copy" style="margin-top:24px"><p class="lesson-step-label">STEP ${step+1} OF 3 · ${steps[step]}</p><h2>${esc(step===1?q.q:steps[step])}</h2>${paragraphs([q.teach,q.answer,q.example][step])}${step===2?`<div class="notice">Remember the connection: ${esc(q.correct)}</div>`:''}${sources(q)}</section><div class="actions">${step?'<button id="lesson-prev">← Back</button>':''}${step<2?'<button class="primary" id="lesson-next">Next step →</button>':`<button class="primary" id="lesson-practice">Try this topic →</button><button id="lesson-complete">${progress.lessons[q.id]?'✓ Lesson completed':'Mark lesson read'}</button>`}</div>${[15,16,17].includes(number)?'<p><button data-view="math">Open the step-by-step formula lab</button></p>':''}</div>`;if($('#lesson-prev'))$('#lesson-prev').onclick=()=>openLesson(number,step-1);if($('#lesson-next'))$('#lesson-next').onclick=()=>openLesson(number,step+1);if($('#lesson-complete'))$('#lesson-complete').onclick=()=>{progress.lessons[q.id]=true;save();openLesson(number,2)};if($('#lesson-practice'))$('#lesson-practice').onclick=()=>{progress.lessons[q.id]=true;save();start('practice',[q,...D.checks.filter(c=>c.source===number)],number)};$('#app').focus()}
function sectionCards(){return `<div class="grid">${D.sections.map(s=>{const qs=D.questions.filter(q=>q.section===s.id),done=qs.filter(completed).length;return `<section class="card"><span class="tag">${esc(s.reading)}</span><h2>${esc(s.title)}</h2><div class="bar"><span style="width:${100*done/qs.length}%"></span></div><p>${done} / ${qs.length} guide prompts answered correctly${done===qs.length?' · ✓ Complete':''}</p><div class="actions"><button class="primary" data-practice-section="${s.id}">Practice this section</button></div></section>`}).join('')}</div>`}
function practiceHome(){const pool=filtered(D.questions),done=pool.filter(completed).length;$('#app').innerHTML=heading('Practice the study guide','Choose answers—no written responses required. Missed questions return later until you get them right.')+`<section class="focus"><div><h2>${done} of ${pool.length} guide prompts completed</h2><p>One correct answer fills that prompt’s completion credit. Extra practice and vocabulary are tracked separately.</p><div class="actions"><button class="primary" id="quick">Review 10</button><button id="all-guide">Practice all ${pool.length}</button><button id="mixed-topic">Mix in terms & activities</button></div></div><div class="ring">${Math.round(100*done/pool.length)}%<small>COMPLETED</small></div></section>`+sectionCards()+`<div class="notice">The full answer after each question covers all parts of the original prompt. For smaller checks on individual details, use Apply your knowledge. Completion shows practice done, not a guarantee of exam readiness.</div>`;$('#quick').onclick=()=>{const rank=x=>{const p=progress.cards[x.id];return p?.level===0?0:!p?1:p.due<=Date.now()?2:3};start('practice',shuffle(pool).sort((a,b)=>rank(a)-rank(b)).slice(0,10))};$('#all-guide').onclick=()=>start('practice',shuffle(pool));$('#mixed-topic').onclick=()=>start('practice',shuffle(filtered(mixedPool())).slice(0,20))}
function mixedPool(){return [...D.questions,...D.vocab,...D.cloze,...D.sorts.map(x=>({...x,kind:'sort'})),...D.vocab.filter(x=>x.exp).map(x=>({...x,id:x.id+'-build',kind:'wordbank',q:`${["PI","AI","PO","AO"].includes(x.term)?"In the process-measurement formulas, build":"Build"} the full name of ${x.term}`}))]}
function prepare(x){if(x.kind==='sort')return {...x,current:shuffledOrder(x.items)};if(x.kind==='wordbank')return {...x,bank:shuffledOrder(x.exp.split(/\s+/).map((word,i)=>({word,i}))),picked:[]};return {...x,options:shuffle([x.correct,...x.distractors])}}
function start(mode,items,lessonNumber=null){if(!items.length){$('#app').innerHTML='<section class="card"><h2>No items in this selection</h2><button data-view="practice">Choose another topic</button></section>';return}session={mode,items:items.map(prepare),index:0,total:items.length,cleared:new Set(),first:{},right:0,graded:false,revealed:false,lessonNumber};renderSession();window.scrollTo(0,0)}
function preteach(x){const q=source(x);return `<details class="card"><summary>Teach me first · show the rule</summary><div class="lesson-copy">${paragraphs(x.teach)}${q?`<p><strong>Example:</strong> ${esc(x.example||q.example)}</p>`:''}</div></details>`}
function feedback(x,ok){const q=source(x);return `<div class="feedback" role="status"><strong>${ok?'✓ Correct':'Not quite — let’s make it simple'}</strong><h3>${x.kind==='sort'?'Correct order':x.kind==='wordbank'?'Full name':'Correct answer'}</h3>${paragraphs(x.kind==='sort'?x.items.join(' → '):x.kind==='wordbank'?x.exp:x.correct)}<h3>Why this fits</h3>${paragraphs(x.teach)}${q?`<h3>Picture the action</h3>${paragraphs(x.example||q.example)}<details><summary>Read the complete study-guide answer</summary>${paragraphs(q.answer)}</details>`:''}${sources(x)}</div>`}
function sessionHeader(x){const s=session;return `<div class="study"><div class="row spread"><span class="tag">${label(x)}</span><button data-view="${s.mode==='flash'?'flash':s.mode==='exam'?'exam':'practice'}">End session</button></div><p class="tiny">${s.mode==='exam'?'Exam':s.mode==='flash'?'Flashcards':'Practice'} · ${Math.min(s.index+1,s.items.length)} / ${s.items.length}${s.mode!=='exam'&&s.mode!=='flash'?` · ${s.cleared.size}/${s.total} cleared`:''}</p><div class="bar"><span style="width:${100*(s.mode==='exam'?s.index:s.cleared.size)/s.total}%"></span></div>`}
function renderSession(){const s=session;if(!s||s.index>=s.items.length){finish();return}chrome();const x=s.items[s.index];s.graded=false;s.revealed=false;if(s.mode==='flash'){renderFlash(x);return}if(x.kind==='sort'){renderSort(x);return}if(x.kind==='wordbank'){renderWordBank(x);return}$('#app').innerHTML=sessionHeader(x)+`${x.number&&({24:1,25:1,26:1,46:1,48:1})[x.number]?`<p class="tiny muted">${esc(({24:"Comparing BPM, BPI, and BPR",25:"Comparing BPM, BPI, and BPR",26:"Choosing BPI or BPR",46:"FAIS and EIS",48:"Enterprise Resource Planning"})[x.number])}</p>`:""}<h2 class="question">${esc(x.q)}</h2>${s.mode==='exam'?'':preteach(x)}<p class="eyebrow">CHOOSE ONE ANSWER</p><div class="choices">${x.options.map((o,i)=>`<button data-option="${i}"><b>${String.fromCharCode(65+i)}.</b><span>${esc(o)}</span></button>`).join('')}</div><div id="feedback"></div></div>`;document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{if(s.graded)return;const answer=x.options[+b.dataset.option];document.querySelectorAll('[data-option]').forEach(btn=>{btn.disabled=true;if(x.options[+btn.dataset.option]===x.correct)btn.classList.add('correct')});if(answer!==x.correct)b.classList.add('wrong');grade(x,answer===x.correct,answer)})}
function grade(x,ok,selected){const s=session;if(s.graded)return;s.graded=true;s.lastOK=ok;if(!(x.id in s.first)){s.first[x.id]={ok,selected};if(ok)s.right++}if(ok)s.cleared.add(x.id);record(x,ok);$('#feedback').innerHTML=feedback(x,ok)+`<button class="primary" id="next">${s.index+1===s.items.length&&(ok||s.mode==='exam')?'See results':'Continue →'}</button>`;$('#next').onclick=advance}
function advance(){const s=session,x=s.items[s.index];if(!s.lastOK&&s.mode!=='exam')s.items.splice(Math.min(s.index+4,s.items.length),0,prepare(x));s.index++;renderSession();$('#app').focus()}
function finish(){const s=session;if(!s)return;const missed=Object.entries(s.first).filter(([,v])=>!v.ok).map(([id])=>s.items.find(x=>x.id===id));$('#app').innerHTML=`<div class="study"><section class="card"><div class="eyebrow">CIS 304 · SESSION COMPLETE</div><h1>${s.mode==='exam'?`${s.right} / ${s.total} on first attempts`:s.mode==='flash'?'Recall round completed':'Every item cleared ✓'}</h1><p>${s.mode==='exam'?'Your score uses your first answer to each question. Review missed topics below.':`You answered or recalled all ${s.total} items successfully, including any retries.`}</p><p>${missed.length} item${missed.length===1?'':'s'} needed another look on the first attempt.</p><div class="actions"><button class="primary" data-view="practice">Back to practice</button>${missed.length?'<button id="retry-missed">Practice missed items</button>':''}${s.lessonNumber?`<button data-lesson="${s.lessonNumber}">Return to the lesson</button>`:''}</div></section>${s.mode==='exam'?missed.map(x=>`<details class="card exam-review"><summary>${esc(x.q)}</summary>${feedback(x,false)}</details>`).join(''):''}</div>`;if($('#retry-missed'))$('#retry-missed').onclick=()=>start('practice',shuffle(missed))}
function flashHome(){$('#app').innerHTML=heading('Flip, remember, repeat','Think of the answer, then tap the card. Mark honestly: remembered cards earn completion credit, and missed cards come back.')+`<div class="grid"><section class="card"><h2>Study-guide flashcards</h2><p>${filtered(D.questions).length} original prompts with complete answers.</p><button class="primary" id="flash-guide">Study guide cards</button></section><section class="card"><h2>Vocabulary flashcards</h2><p>${filtered(D.vocab).length} terms, including full abbreviation names.</p><button class="primary" id="flash-vocab">Study terms</button></section></div>`;$('#flash-guide').onclick=()=>start('flash',shuffle(filtered(D.questions)));$('#flash-vocab').onclick=()=>start('flash',shuffle(filtered(D.vocab)))}
function renderFlash(x){const s=session;$('#app').innerHTML=sessionHeader(x)+`<p class="eyebrow" id="flash-side">FRONT · TAP TO REVEAL</p><button class="card flashcard" id="flip" aria-label="Reveal answer"><h2>${esc(x.term||x.q)}</h2></button><div id="rating"></div></div>`;$('#flip').onclick=()=>{s.revealed=!s.revealed;$('#flash-side').textContent=s.revealed?'BACK · TAP TO HIDE':'FRONT · TAP TO REVEAL';$('#flip').setAttribute('aria-label',s.revealed?'Hide answer':'Reveal answer');$('#flip').innerHTML=s.revealed?`${x.exp?`<h2>${esc(x.exp)}</h2>`:''}${paragraphs(x.answer)}`:`<h2>${esc(x.term||x.q)}</h2>`;$('#rating').innerHTML=s.revealed?`<div class="actions"><button id="forgot">Still learning · show again</button><button class="primary" id="remembered">I remembered it</button></div><details><summary>Help me understand</summary>${paragraphs(x.teach)}</details>`:'';if(s.revealed){$('#forgot').onclick=()=>rate(false);$('#remembered').onclick=()=>rate(true)}};function rate(ok){if(s.graded)return;s.graded=true;s.lastOK=ok;if(!(x.id in s.first)){s.first[x.id]={ok};if(ok)s.right++}if(ok)s.cleared.add(x.id);record(x,ok);advance()}}
function applyHome(){$('#app').innerHTML=heading('Apply your knowledge','Extra checks on the same guide topics, kept separate from the original prompts.')+`<section class="card"><h2>${filtered(D.checks).length} focused checks</h2><p>Recognize examples, distinguish similar terms, and test individual parts of multi-part guide questions.</p><button class="primary" id="apply-start">Practice these checks</button><button id="cloze-start">Fill-in-the-blank choices</button></section>`;$('#apply-start').onclick=()=>start('practice',shuffle(filtered(D.checks)));$('#cloze-start').onclick=()=>start('practice',shuffle(filtered(D.cloze)))}
function sortHome(){$('#app').innerHTML=heading('Put the steps in order','Every attempt starts shuffled. These are specific example sequences, not a claim that every business uses identical steps.')+`<div class="grid">${filtered(D.sorts).map(x=>`<section class="card"><h2>${esc(x.q)}</h2><p>${label(x)}</p><button class="primary" data-sort="${x.id}">Build this sequence</button></section>`).join('')}</div>${filtered(D.sorts).length?'':'<p>No sequence activities in this section. Select All topics to see them.</p>'}`}
function renderSort(x){$('#app').innerHTML=sessionHeader(x)+`<h2>${esc(x.q)}</h2>${preteach(x)}<div class="order">${x.current.map((v,i)=>`<div><b>${i+1}</b><span>${esc(v)}</span><button data-move="${i}" data-delta="-1" aria-label="Move ${esc(v)} up" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-delta="1" aria-label="Move ${esc(v)} down" ${i===x.current.length-1?'disabled':''}>↓</button></div>`).join('')}</div><button class="primary" id="check-order">Check order</button><div id="feedback"></div></div>`;document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=+b.dataset.move,j=i+(+b.dataset.delta);[x.current[i],x.current[j]]=[x.current[j],x.current[i]];renderSort(x)});$('#check-order').onclick=()=>{if(session.graded)return;document.querySelectorAll('[data-move],#check-order').forEach(b=>b.disabled=true);grade(x,x.current.every((v,i)=>v===x.items[i]))}}
function abbrevHome(){const items=filtered(D.vocab).filter(v=>v.exp);$('#app').innerHTML=heading('Abbreviations, fully understood','Choose the name or build it one word at a time. Then connect it to what it actually means.')+`<section class="card"><h2>${items.length} abbreviations</h2><p>${items.map(v=>esc(v.term)).join(' · ')}</p><div class="actions"><button class="primary" id="abbrev-choice">Choose the full name</button><button id="abbrev-build">Build with a word bank</button></div></section>`;$('#abbrev-choice').onclick=()=>start('practice',shuffle(items.map(v=>({...v,id:v.id+'-name',q:`${["PI","AI","PO","AO"].includes(v.term)?"In the process-measurement formulas":"In this CIS 304 course"}, what does ${v.term} stand for?`,correct:v.exp,distractors:D.abbreviationDistractors[v.term]}))));$('#abbrev-build').onclick=()=>start('practice',shuffle(items.map(v=>({...v,id:v.id+'-build',kind:'wordbank',q:`${["PI","AI","PO","AO"].includes(v.term)?"In the process-measurement formulas, build":"Build"} the full name of ${v.term}`}))))}
function renderWordBank(x){$('#app').innerHTML=sessionHeader(x)+`<h2>${esc(x.q)}</h2><p>Tap words in order. Tap a selected word to return it to the bank.</p><div class="word-answer"><div class="wordbank">${x.picked.map((v,i)=>`<button data-remove="${i}">${esc(v.word)} ×</button>`).join('')||'<span class="muted">Your answer will appear here</span>'}</div></div><div class="wordbank">${x.bank.map(v=>`<button data-word="${v.i}" ${x.picked.some(w=>w.i===v.i)?'disabled':''}>${esc(v.word)}</button>`).join('')}</div><button class="primary" id="check-bank" ${x.picked.length!==x.bank.length?'disabled':''}>Check name</button><div id="feedback"></div></div>`;document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{x.picked.push(x.bank.find(w=>w.i===+b.dataset.word));renderWordBank(x)});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{x.picked.splice(+b.dataset.remove,1);renderWordBank(x)});$('#check-bank').onclick=()=>{if(session.graded)return;document.querySelectorAll('[data-word],[data-remove],#check-bank').forEach(b=>b.disabled=true);grade(x,x.picked.map(v=>v.word).join(' ')===x.exp)}}
function termsHome(){$('#app').innerHTML=heading('Words you can actually understand','Definitions are tied to the same guide topics. Open the related lesson for context.')+`<label class="search-label">Find a term<input type="search" id="search" placeholder="Try: input, enterprise, ERP…"></label><div class="wordlist" id="terms"></div>`;function update(){const str=$('#search').value.toLowerCase(),vs=filtered(D.vocab).filter(v=>(v.term+' '+v.exp+' '+v.answer).toLowerCase().includes(str));$('#terms').innerHTML=vs.map(v=>`<article><span class="tag">${label(v)}</span><h3>${esc(v.term)}${v.exp?' · '+esc(v.exp):''}</h3>${paragraphs(v.answer)}${paragraphs(v.teach)}<button data-lesson="${v.source}">See it in context</button></article>`).join('')||'<p>No matching terms.</p>'}$('#search').oninput=update;update()}
function guideHome(){$('#app').innerHTML=heading('All 51 prompts. Fully answered.','Original wording is preserved, including multi-part prompts. Answers fill the blanks using course slides and supporting references.')+`<div class="notice">${filtered(D.questions).length} of 51 prompts shown. Brief prompts such as “How are they similar?” retain their original wording; the title supplies their context. Slide 20 controls the course formulas. The EA properties answer is a synthesis because the materials do not name a separate fixed list.</div><div class="lesson-list">${filtered(D.questions).map(q=>`<article class="card"><span class="tag">${label(q)} · Guide ${q.number}</span><h3>${esc(q.title)}</h3><details><summary>${esc(q.q)}</summary><div class="lesson-copy">${paragraphs(q.answer)}<h3>Let’s make it simple</h3>${paragraphs(q.teach)}<h3>Example</h3>${paragraphs(q.example)}</div>${sources(q)}<div class="actions"><button data-lesson="${q.number}">Teach me step by step</button><button data-question="${q.number}">Practice this prompt</button></div></details></article>`).join('')}</div>`}
function readingsHome(){$('#app').innerHTML=heading('Your assigned readings','Use these as supporting references for the study guide. Required readings and extra resources stay separate.')+`<div class="notice">All 40 supplied links are organized below, including both Zoom videos. Canvas “Links to an external site” text has been removed. The first Systems Thinking URL was recovered from slide 13. Videos are linked for viewing; the app does not claim to contain verified transcripts of them.</div>`+[1,2,3].map(n=>`<section class="card" style="margin-top:22px"><h2>Reading Set ${n}</h2><ul class="reading-list">${D.readings.filter(r=>r.set===n&&!r.extra).map(readingLink).join('')}</ul><details><summary>Extra resources (${D.readings.filter(r=>r.set===n&&r.extra).length})</summary><ul class="reading-list">${D.readings.filter(r=>r.set===n&&r.extra).map(readingLink).join('')}</ul></details></section>`).join('')}
function readingLink(r){return `<li><a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.title)}</a></li>`}
function examHome(){$('#app').innerHTML=heading('Practice exam','A new shuffled exam each time. First choices count toward the score; explanations appear after each answer.')+`<section class="card"><h2>Choose your practice</h2><div class="row"><label>Bank <select id="bank"><option value="guide">Original study-guide prompts</option><option value="mixed">Guide + detailed understanding checks</option><option value="terms">Vocabulary</option></select></label><label>Length <select id="length"><option value="10">10</option><option value="20" selected>20</option><option value="9999">Entire selected bank</option></select></label></div><p>Missed items can be practiced again after the exam. No pre-answer explanation is shown in exam mode.</p><button class="primary" id="exam-start">Generate exam</button></section>`;$('#exam-start').onclick=()=>{const b=$('#bank').value;start('exam',shuffle(filtered(b==='guide'?D.questions:b==='terms'?D.vocab:[...D.questions,...D.checks])).slice(0,+$('#length').value))}}
let mathCase=null,mathStep=0;
const fmt=n=>Number(n.toFixed(3)).toLocaleString('en-US');
function generateMath(previous){let c;do{const pi=[8,10,12,16,20][Math.floor(Math.random()*5)],ai=[5,8,10,15,20][Math.floor(Math.random()*5)],po=[60,80,100,120,160][Math.floor(Math.random()*5)],ao=[40,60,80,100,120,160][Math.floor(Math.random()*6)];c={pi,ai,po,ao}}while(previous&&Object.keys(c).every(k=>c[k]===previous[k]));return c}
function mathHome(){if(!mathCase)mathCase=generateMath();const c=mathCase;$('#app').innerHTML=heading('Formula lab','Use the exact slide 20 formulas. Watch the substitution, then try new numbers with answer choices.')+`<details class="card" open><summary>Keep these formulas beside you</summary><div class="lesson-copy"><p><b>Input</b> = resources used, such as labor hours. <b>Output</b> = results produced, such as acceptable orders.</p><p><b>Planned</b> = the initial target. <b>Actual</b> = what really happened.</p><p><b>Efficiency = PI ÷ AI.</b> Compare resource use with the plan.</p><p><b>Effectiveness = AO ÷ PO.</b> Compare the achieved result with the target.</p><p><b>Productivity = AO ÷ AI.</b> Find useful output per resource unit.</p><p>Efficiency and effectiveness are ratios: multiply by 100 for percentages. Productivity has units, such as orders per hour. Use comparable work and units; more output is not automatically better if quality suffers.</p></div></details><section class="card" style="margin-top:22px"><h2>A bakery’s order-packing shift</h2><p>Compare what the manager initially planned with what the team actually did.</p><div class="formula-grid"><div>PI · Planned input<strong>${c.pi} labor hours</strong>Resources expected</div><div>AI · Actual input<strong>${c.ai} labor hours</strong>Resources really used</div><div>PO · Planned output<strong>${c.po} acceptable orders</strong>Target result</div><div>AO · Actual output<strong>${c.ao} acceptable orders</strong>Actual result</div></div><div id="math-work"></div><div class="actions"><button id="math-next" class="primary">Show the first calculation</button><button id="math-new">New numbers</button><button id="math-practice">Try a fresh practice round</button></div></section>`;mathStep=0;$('#math-next').onclick=showMathStep;$('#math-new').onclick=()=>{mathCase=generateMath(c);mathHome()};$('#math-practice').onclick=()=>{mathCase=generateMath(c);start('practice',mathQuestions(mathCase))}}
function showMathStep(){const c=mathCase,steps=[`1. Efficiency uses input only. Planned ${c.pi} hours ÷ actual ${c.ai} hours = ${fmt(c.pi/c.ai)}. Multiply by 100: ${fmt(c.pi/c.ai*100)}%. ${c.ai<c.pi?'Fewer hours were used than planned.':c.ai>c.pi?'More hours were used than planned.':'Actual resource use matched the plan.'}`,`2. Effectiveness uses output only. Actual ${c.ao} orders ÷ planned ${c.po} orders = ${fmt(c.ao/c.po)} = ${fmt(c.ao/c.po*100)}%. ${c.ao<c.po?'The team fell short of the output target.':c.ao>c.po?'The team exceeded the output target.':'The team met the output target.'}`,`3. Productivity connects output and input. Actual ${c.ao} orders ÷ actual ${c.ai} hours = ${fmt(c.ao/c.ai)} orders per labor hour. This is a rate, not a percentage.`,`4. Compare over time. Planned productivity was ${c.po} ÷ ${c.pi} = ${fmt(c.po/c.pi)} orders/hour. Actual productivity is ${fmt(c.ao/c.ai)} orders/hour. Percentage change from that planned baseline is (${fmt(c.ao/c.ai)} − ${fmt(c.po/c.pi)}) ÷ ${fmt(c.po/c.pi)} × 100 ≈ ${fmt(((c.ao/c.ai)/(c.po/c.pi)-1)*100)}%. Calculations use unrounded values; displayed decimals are rounded.`];if(mathStep>=steps.length)return;$('#math-work').insertAdjacentHTML('beforeend',`<div class="formula-step">${esc(steps[mathStep++])}</div>`);$('#math-next').textContent=mathStep===4?'All steps shown':'Show next calculation →';$('#math-next').disabled=mathStep===4}
function mathQuestions(c){const scenario=`Planned: ${c.pi} hours and ${c.po} acceptable orders. Actual: ${c.ai} hours and ${c.ao} acceptable orders.`;return [
 {q:'Which value is actual input (AI)?',correct:`${c.ai} labor hours`,distractors:[`${c.ao} acceptable orders`,`${c.po} orders planned`,`${c.pi} hours planned`],teach:'Actual input means the resources really used. Here those resources are labor hours, not the orders produced.',source:15},
 ...[{source:15,name:'efficiency',value:c.pi/c.ai*100,unit:'%',rule:`PI / AI = ${c.pi} / ${c.ai}. Multiply the ratio by 100 for a percentage.`},{source:16,name:'effectiveness',value:c.ao/c.po*100,unit:'%',rule:`AO / PO = ${c.ao} / ${c.po}. Actual output is on top; planned output is the target.`},{source:17,name:'productivity',value:c.ao/c.ai,unit:' orders per hour',rule:`AO / AI = ${c.ao} / ${c.ai}. Divide actual orders by actual labor hours. Do not multiply by 100; the result is a rate.`}].map(r=>({q:`What is ${r.name}? Round to three decimal places when needed.`,correct:fmt(r.value)+r.unit,distractors:[.5,1.25,2].map(f=>fmt(r.value*f)+r.unit),teach:r.rule,source:r.source}))
 ].map((x,i)=>({...x,id:`304-math-${c.pi}-${c.ai}-${c.po}-${c.ao}-${i}`,section:2,example:scenario,q:scenario+' '+x.q,answer:x.correct}))}
const mapViews={
 layers:{title:'The four enterprise architecture layers',intro:'These are connected views of one enterprise. They are not the networking layers from CIS 320.',parts:[['Business','What work and decisions serve the goal?','A bakery wants customers to collect accurate orders quickly. Business architecture describes ordering, fulfillment, responsibilities, and rules.',29],['Data','What information does that work need?','Customer, product, order, payment, and stock records. Data architecture defines how these records are structured and managed.',29],['Application','Which programs use the information and perform the work?','Ordering, inventory, and accounting applications must interact so one sale reaches the teams that need it.',29],['Technology','What technical capabilities run those programs?','Servers or cloud resources, operating systems, storage, and networks support the applications. The actual chosen resources are infrastructure.',29]]},
 processes:{title:'One business, four connected processes',intro:'The bakery is the same business throughout. Follow what moves into it, through it, and out to customers.',parts:[['Procurement','Get flour and other resources','A need triggers purchasing. The bakery selects a supplier, sends an order, receives and checks flour, and pays. Output: usable supplies and purchase records.',19],['Production','Turn resources into value','Bakers combine flour, time, and ovens to produce bread. In a service business this step could be performing a haircut instead of making an object.',19],['Fulfillment','Meet the customer’s order','Staff receive an order, prepare the bread for the customer, deliver it, and handle payment. Timing of payment depends on the business.',19],['Accounting','Track the financial events across the work','Accounting receives purchase, sale, and payment records. It checks, classifies, and summarizes them into financial reports. It connects with all three other processes; it is not just a final step.',19]]},
 erp:{title:'A customer order crosses departments',intro:'Click each team to see why a shared record matters. This illustrates an ERP-supported flow, not a required sequence for every business.',parts:[['Sales','Enter the customer order','Sales records what the customer wants. Other teams can use the same order instead of retyping it.',47],['Inventory / operations','Check stock or arrange production','Staff see what is needed and whether enough stock exists. They can reserve items or plan work using the order information.',47],['Warehouse / fulfillment','Prepare and deliver','Staff use the shared order to pick the right items and record shipment. The order’s status becomes visible to other teams.',47],['Accounting','Bill and record payment','Accounting uses the connected transaction to bill accurately and record money received. Shared information helps reduce inconsistent copies.',47]]},
 flow:{title:'A process model: is the ordered item available?',intro:'An actor performs an activity. A decision chooses a path. This simple example shows both outcomes of the decision.',parts:[['Receive customer order','Sales or an ordering system','Input: what the customer wants. The actor records the order so it can be checked.',13],['Check stock','Inventory staff or software','An activity checks whether the requested quantity is available. It produces information for the next decision.',13],['Enough stock?','A decision with yes/no paths','YES → prepare and deliver the order. NO → notify the customer and arrange a wait, alternative, or cancellation. The chosen business rules determine what happens next.',13],['Complete the chosen path','Result / output','The result may be a delivered order or an agreed alternative/cancellation. A complete model must show these paths rather than assuming every order succeeds.',13]]}
};
function mapHome(selected='layers'){const m=mapViews[selected];$('#app').innerHTML=heading('See how the pieces connect','Move from the business goal to its processes, information, applications, and technology.')+`<div class="actions">${Object.entries(mapViews).map(([k,m])=>`<button data-map="${k}" ${k===selected?'class="dark" aria-pressed="true"':'aria-pressed="false"'}>${esc(m.title)}</button>`).join('')}</div><section class="card" style="margin-top:24px"><h2>${m.title}</h2><p>${m.intro}</p><div class="${selected==='layers'?'map-stack':'flow304'}">${m.parts.map((p,i)=>`<button data-map-part="${i}" aria-pressed="${i===0}"><b>${esc(p[0])}</b><br><span class="tiny">${esc(p[1])}</span></button>`).join('')}</div><div id="map-detail" class="notice" aria-live="polite"></div></section>`;function detail(i){const p=m.parts[i];$('#map-detail').innerHTML=`<h3>${esc(p[0])}</h3>${paragraphs(p[2])}<button data-lesson="${p[3]}">Learn this guide topic</button>`;document.querySelectorAll('[data-map-part]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.mapPart===i)))}document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>mapHome(b.dataset.map));document.querySelectorAll('[data-map-part]').forEach(b=>b.onclick=()=>detail(+b.dataset.mapPart));detail(0)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view)navigate(b.dataset.view);else if(b.dataset.lesson)openLesson(+b.dataset.lesson);else if(b.dataset.practiceSection){section=+b.dataset.practiceSection;view='practice';start('practice',shuffle(filtered(D.questions)))}else if(b.dataset.question)start('practice',[D.questions.find(q=>q.number===+b.dataset.question)]);else if(b.dataset.sort)start('practice',[{...D.sorts.find(x=>x.id===b.dataset.sort),kind:'sort'}])});
fetch('cis304-content.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Could not load study content');return r.json()}).then(data=>{D=data;render()}).catch(()=>{$('#app').innerHTML='<section class="card"><h1>Study content could not load</h1><p>Refresh the page to try again. CIS 304 needs cis304-content.json alongside this page.</p><button onclick="location.reload()">Try again</button></section>'});
